"""Topic path subscription matcher."""
def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    # Split patterns and topics into segments
    pattern_segments = subscribed_pattern.split("::")
    topic_segments = event_topic.split("::")

    # If pattern has more segments than topic, it's not a match
    if len(pattern_segments) > len(topic_segments):
        return False

    # Check each segment of the pattern against the topic
    for i, pattern_segment in enumerate(pattern_segments):
        if pattern_segment == "**":
            # Double asterisk matches any prefix - no further checks needed
            return True
        elif pattern_segment == "*":
            # Single asterisk matches exactly one segment, continue
            continue
        elif pattern_segment != topic_segments[i]:
            return False

    # If all pattern segments matched, it's a valid subscription
    return True

def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
=== END ===
